// CETE H4.7 Stage 5E.2K.6C.1: exact RETURN_VALUE signal + purged chronological ridge forecast.
// OFFLINE ONLY. Outcomes never enter features. No changes to trading model/checkpoint.
#include "devai/strategy/dev_ai_strategy/DevHistoricalTrainingCache.hpp"
#include "devai/strategy/dev_ai_strategy/DevAIObservation.hpp"
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <limits>
#include <map>
#include <set>
#include <stdexcept>
#include <string>
#include <vector>
namespace ds=devai::strategy; namespace fs=std::filesystem;
namespace {
using Vec=std::array<double,4>; using Matrix=std::array<Vec,4>;
struct Sample {std::int64_t t=0, end=0;std::string symbol;int rank=0,h=0;bool eligible=false;Vec x{};double y=0;};
struct Metric {std::size_t n=0,positive=0;double se=0,ae=0,dir=0,sumY=0,sumPred=0;void add(double p,double y){++n;se+=(p-y)*(p-y);ae+=std::abs(p-y);dir+=((p>0)==(y>0)?1.:0.);positive+=(y>0);sumY+=y;sumPred+=p;}};
void require(bool b,const std::string& m){if(!b)throw std::runtime_error(m);}
int minuteIST(std::int64_t t){auto s=(t+19800)%86400;if(s<0)s+=86400;return static_cast<int>(s/60);}
std::int64_t dayIST(std::int64_t t){auto s=t+19800; if(s<0 && s%86400) s-=86400;return s/86400;}
Vec features(const ds::DevAIObservation& o){Vec x{1.,0.,0.,0.};int j=1;for(auto tf:{ds::DevTimeframe::ONE_MINUTE,ds::DevTimeframe::FIVE_MINUTE,ds::DevTimeframe::FIFTEEN_MINUTE}){auto i=ds::marketIndex(tf,ds::DevMetric::RETURN_VALUE);require(o.availability[i]==1. && std::isfinite(o.market[i]),"Missing RETURN_VALUE feature");x[j++]=o.market[i];}return x;}
bool eligible(const ds::DevAIObservation& o){if(!o.ready||!o.numerical_integrity)return false;for(auto tf:{ds::DevTimeframe::ONE_MINUTE,ds::DevTimeframe::FIVE_MINUTE,ds::DevTimeframe::FIFTEEN_MINUTE}){auto i=ds::marketIndex(tf,ds::DevMetric::RETURN_VALUE);if(o.availability[i]!=1. || !std::isfinite(o.market[i]) || o.market[i]<=0.)return false;}return true;}
Vec solve(Matrix a,Vec b){for(int i=0;i<4;++i){int pivot=i;for(int j=i+1;j<4;++j)if(std::abs(a[j][i])>std::abs(a[pivot][i]))pivot=j;require(std::abs(a[pivot][i])>1e-15,"Singular regression matrix");std::swap(a[i],a[pivot]);std::swap(b[i],b[pivot]);double d=a[i][i];for(int k=i;k<4;++k)a[i][k]/=d;b[i]/=d;for(int j=0;j<4;++j)if(j!=i){double f=a[j][i];for(int k=i;k<4;++k)a[j][k]-=f*a[i][k];b[j]-=f*b[i];}}return b;}
Vec fit(const std::vector<Sample>& v,int h,std::int64_t boundary,double lambda,std::size_t& count){Matrix a{};Vec b{};count=0;for(const auto& s:v){if(s.h!=h || s.t>=boundary || s.end>=boundary)continue;++count;for(int i=0;i<4;++i){b[i]+=s.x[i]*s.y;for(int j=0;j<4;++j)a[i][j]+=s.x[i]*s.x[j];}}require(count>=30,"Too few purged training labels");for(int i=1;i<4;++i)a[i][i]+=lambda;return solve(a,b);}
double predict(const Vec& w,const Vec& x){double p=0;for(int i=0;i<4;++i)p+=w[i]*x[i];return p;}
std::vector<std::string> csv(const std::string& line){std::vector<std::string> v;std::string c;bool quote=false;for(std::size_t i=0;i<line.size();++i){if(line[i]=='"'){if(quote && i+1<line.size()&&line[i+1]=='"'){c+='"';++i;}else quote=!quote;}else if(line[i]==','&&!quote){v.push_back(c);c.clear();}else c+=line[i];}require(!quote,"Invalid quoted CSV");v.push_back(c);return v;}
std::size_t checkLedger(const fs::path& path,const ds::DevHistoricalTrainingDataset& data,const fs::path& out){std::ifstream in(path);require(bool(in),"Cannot open ledger");std::string line;require(bool(std::getline(in,line)),"Empty ledger");auto header=csv(line);std::map<std::string,std::size_t> idx;for(std::size_t i=0;i<header.size();++i)idx[header[i]]=i;for(auto k:{"decision_time","desired_symbol","held_symbol","quantity"})require(idx.count(k),std::string("Ledger missing ")+k);std::ofstream report(out);require(bool(report),"Cannot write reconstruction report");report<<"decision_time,expected_desired,ledger_desired,match,previous_held,ledger_held_after\n";std::size_t row=0,mismatch=0;std::string heldBefore;while(std::getline(in,line)){if(line.empty())continue;auto cells=csv(line);require(cells.size()==header.size(),"Ledger CSV width mismatch");require(row<data.records.size(),"Ledger has more rows than cache");const auto& r=data.records[row++];auto t=std::stoll(cells[idx.at("decision_time")]);require(t==r.decision_time,"Ledger/cache decision timestamps differ");const int now=minuteIST(t);std::string expected;
if(now>=915)expected="";else if(!heldBefore.empty()){for(const auto& c:r.candidates)if(c.symbol==heldBefore && eligible(c.observation)){expected=heldBefore;break;}}
else if(now<885){for(const auto& c:r.candidates)if(eligible(c.observation)){expected=c.symbol;break;}}
const auto& desired=cells[idx.at("desired_symbol")];bool match=expected==desired;if(!match)++mismatch;report<<t<<','<<expected<<','<<desired<<','<<(match?1:0)<<','<<heldBefore<<','<<cells[idx.at("held_symbol")]<<'\n';heldBefore=cells[idx.at("held_symbol")];}
require(row==data.records.size(),"Ledger has fewer rows than cache");std::cout<<"Exact policy desired-symbol reconstruction: "<<(row-mismatch)<<'/'<<row<<" matches; mismatches="<<mismatch<<'\n';require(mismatch==0,"Policy reconstruction mismatch: inspect signal_reconstruction.csv; forecast not fitted");return row;}
void reportMetric(std::ofstream& out,const std::string& split,int h,const std::string& group,const Metric& m){if(!m.n)return;out<<split<<','<<h<<','<<group<<','<<m.n<<','<<std::sqrt(m.se/m.n)<<','<<m.ae/m.n<<','<<m.dir/m.n<<','<<m.positive/static_cast<double>(m.n)<<','<<m.sumY/m.n<<','<<m.sumPred/m.n<<'\n';}
}
int main(int argc,char**argv){try{require(argc==5,"Usage: run_cete_h47_stage6c1_forecast <enriched.cache> <math_ledger.csv> <output_dir> <ridge_lambda>");const fs::path out(argv[3]);fs::create_directories(out);const double lambda=std::stod(argv[4]);require(std::isfinite(lambda)&&lambda>0,"ridge_lambda must be positive");auto data=ds::DevHistoricalTrainingCache::load(argv[1]);ds::DevHistoricalTrainingDatasetValidator::validate(data);require(!data.records.empty(),"Empty cache");checkLedger(argv[2],data,out/"signal_reconstruction.csv");
std::set<std::int64_t> days;std::vector<Sample> samples;std::map<int,std::size_t> missing;std::size_t signalCount=0,eligibleCount=0;for(const auto& r:data.records){days.insert(dayIST(r.decision_time));for(const auto& c:r.candidates){++signalCount;const bool ok=eligible(c.observation);eligibleCount+=ok;Vec x{};bool usable=r.numerical_integrity&&c.numerical_integrity&&c.observation.ready&&c.observation.numerical_integrity; if(usable){for(auto tf:{ds::DevTimeframe::ONE_MINUTE,ds::DevTimeframe::FIVE_MINUTE,ds::DevTimeframe::FIFTEEN_MINUTE}){auto i=ds::marketIndex(tf,ds::DevMetric::RETURN_VALUE);if(c.observation.availability[i]!=1.||!std::isfinite(c.observation.market[i]))usable=false;}}if(usable)x=features(c.observation);for(const auto& o:c.outcomes){if(o.horizon_bars!=5&&o.horizon_bars!=10&&o.horizon_bars!=15)continue;int h=static_cast<int>(o.horizon_bars);if(!usable||!o.available||!o.numerical_integrity||!std::isfinite(o.forward_return)||o.outcome_time<=r.decision_time){++missing[h];continue;}samples.push_back({r.decision_time,o.outcome_time,c.symbol,static_cast<int>(c.candidate_rank),h,ok,x,o.forward_return});}}}
require(days.size()>=10,"Need >=10 IST sessions for chronological split");std::vector<std::int64_t> d(days.begin(),days.end());const std::size_t trainN=d.size()*6/10,valN=d.size()*2/10;require(trainN>=2&&valN>=1&&trainN+valN<d.size(),"Invalid split");const auto valStart=d[trainN]*86400-19800,testStart=d[trainN+valN]*86400-19800;std::ofstream split(out/"split_manifest.csv");split<<"split,session_count,first_ist_day,last_ist_day,first_epoch,last_epoch\n";for(auto [name,begin,end]:{std::tuple<std::string,std::size_t,std::size_t>{"train",0,trainN},{"validation",trainN,trainN+valN},{"test",trainN+valN,d.size()}})split<<name<<','<<(end-begin)<<','<<d[begin]<<','<<d[end-1]<<','<<(d[begin]*86400-19800)<<','<<(d[end-1]*86400-19800)<<'\n';
std::ofstream coeff(out/"forecast_coefficients.csv"),metrics(out/"forecast_metrics.csv"),preds(out/"forecast_predictions.csv");require(bool(coeff)&&bool(metrics)&&bool(preds),"Cannot create reports");coeff<<"fit,train_end_exclusive,horizon_bars,training_labels_purged,ridge_lambda,intercept,return_value_1m,return_value_5m,return_value_15m\n";metrics<<"split,horizon_bars,group,count,rmse,mae,directional_accuracy,positive_fraction,mean_realized_return,mean_predicted_return\n";preds<<"split,decision_time,outcome_time,symbol,rank,horizon_bars,exact_signal_eligible,predicted_forward_return,realized_forward_return\n";coeff<<std::setprecision(15);metrics<<std::setprecision(15);preds<<std::setprecision(15);
for(int h:{5,10,15}){std::size_t n1=0,n2=0;const auto wVal=fit(samples,h,valStart,lambda,n1);const auto wTest=fit(samples,h,testStart,lambda,n2);for(auto [name,bound,n,w]:{std::tuple<std::string,std::int64_t,std::size_t,Vec>{"validation_fit",valStart,n1,wVal},{"test_refit",testStart,n2,wTest}})coeff<<name<<','<<bound<<','<<h<<','<<n<<','<<lambda<<','<<w[0]<<','<<w[1]<<','<<w[2]<<','<<w[3]<<'\n';std::map<std::pair<std::string,std::string>,Metric> agg;for(const auto& s:samples){if(s.h!=h||s.t<valStart)continue;const bool test=s.t>=testStart;const auto name=test?"test":"validation";const auto p=predict(test?wTest:wVal,s.x);preds<<name<<','<<s.t<<','<<s.end<<','<<s.symbol<<','<<s.rank<<','<<h<<','<<(s.eligible?1:0)<<','<<p<<','<<s.y<<'\n';agg[{name,"all"}].add(p,s.y);agg[{name,s.eligible?"eligible":"ineligible"}].add(p,s.y);}for(const auto& [key,m]:agg)reportMetric(metrics,key.first,h,key.second,m);}
std::ofstream summary(out/"run_summary.csv");summary<<"metric,value\n"<<"sessions,"<<d.size()<<"\n"<<"train_sessions,"<<trainN<<"\n"<<"validation_sessions,"<<valN<<"\n"<<"test_sessions,"<<d.size()-trainN-valN<<"\n"<<"signal_candidates,"<<signalCount<<"\n"<<"exact_eligible_candidates,"<<eligibleCount<<"\n"<<"usable_label_samples,"<<samples.size()<<"\n"<<"ridge_lambda,"<<lambda<<"\n";for(auto [h,n]:missing)summary<<"excluded_h"<<h<<','<<n<<'\n';std::cout<<"[CETE][H47][5E2K6C1] OFFLINE CAUSAL FORECAST COMPLETE\n"<<"Sessions: "<<d.size()<<" train="<<trainN<<" validation="<<valN<<" test="<<d.size()-trainN-valN<<"\n"<<"Exact signal eligible: "<<eligibleCount<<"/"<<signalCount<<" usable horizon labels="<<samples.size()<<"\n"<<"Reports: "<<out<<'\n';return 0;}catch(const std::exception& e){std::cerr<<"[CETE][H47][5E2K6C1] FAIL: "<<e.what()<<'\n';return 1;}}
